import sys
from collections import deque

def bfs_shortest_path(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if distances[neighbor] == float('inf'):
                distances[neighbor] = distances[current] + 1
                queue.append(neighbor)
    return distances

def find_most_popular_friend(group):
    n = len(group)
    total_distances = {node: 0 for node in group}
    min_notoriety = float('inf')
    most_popular_friends = []

    for friend in group:
        distances = bfs_shortest_path(group, friend)
        notoriety = sum(distances.values()) / n
        total_distances[friend] = notoriety
        if notoriety < min_notoriety:
            min_notoriety = notoriety
            most_popular_friends = [friend]
        elif notoriety == min_notoriety:
            most_popular_friends.append(friend)

    most_popular_friends.sort()
    most_popular = most_popular_friends[0]
    return most_popular, total_distances[most_popular]

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    num_groups = int(input[index])
    index += 1
    results = []

    for _ in range(num_groups):
        num_friends = int(input[index])
        index += 1
        group = {}
        for i in range(1, num_friends + 1):
            friends = list(map(int, input[index].split()))
            group[i] = friends
            index += 1
        most_popular, avg_distance = find_most_popular_friend(group)
        results.append(f"{most_popular} {avg_distance:.6f}")

    print("\n".join(results))

if __name__ == "__main__":
    main()
